  const ramus = (s) => t3Loft([[s * 0.062, 0, 0, 0.018, 0.017, 0.8], [s * 0.06, -0.004, 0.03, 0.019, 0.018], [s * 0.045, -0.008, 0.06, 0.016, 0.016], [s * 0.02, -0.01, 0.088, 0.013, 0.013], [s * 0.004, -0.008, 0.1, 0.011, 0.011, 0.8]], 8);
