  if (v === 2 || v === 5) for (const [x, y, z, r] of [[0.035, 0.76, 0.098, 0.015], [-0.035, 0.71, 0.088, 0.013], [0.0, 0.68, 0.09, 0.011]]) { const bl = new THREE.Mesh(GG('gboil', () => t3Blob(1, 0.9, 0.7)), M.bile); place('Spine2', bl, x, y, z); bl.scale.setScalar(r); }   // bolle di bile sul petto
