    pp['elb' + i] = sp('elb' + i, aim ? -0.15 : -0.35 - ((i ? sw : -sw) > 0 ? 0.6 * sf : 0.1 * sf) - (wind ? 1 : 0) + (strike ? 0.9 : 0), 90, 8);
    pp['fc' + i] = sp('fc' + i, (i && u.hasW) ? 1 : 0.3 + 0.12 * sf + (atk ? 0.35 : 0) + (strike ? 0.25 : 0), 40, 7);
