    const el = grp(a, 0, -0.28 * ak, 0); el.rotation.x = -0.35; elbows.push(el); mesh(D.fore, M.skin, el).scale.set(s * kw, ak, kw); mesh(D.foreBone, M.bone, el).scale.set(s * kw, ak, kw);
